def component_stats(arr, color):
 seen=set();cs=[]
 for r in range(arr.shape[0]):
  for c in range(arr.shape[1]):
   if arr[r,c]!=color or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c));n=0
   while q:
    x,y=q.pop();n+=1
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     p=(x+dx,y+dy)
     if 0<=p[0]<arr.shape[0] and 0<=p[1]<arr.shape[1] and arr[p]==color and p not in seen:seen.add(p);q.append(p)
   cs.append(n)
 return sorted(cs,reverse=True)
